3	 * assume a Sample is well-formed.
4	 */
5	
6	export interface Sample {
7	  /** Series name — non-empty, no whitespace. */
8	  series: string;
9	  /** The measured value; finite. */
10	  value: number;
11	  /** Epoch milliseconds. */
12	  at: number;
13	}
