16	  readonly field: string;
17	
18	  constructor(field: string, message: string) {
19	    super(`${field}: ${message}`);
20	    this.name = "ValidationError";
21	    this.field = field;
22	  }
23	}
24	
25	export function isFiniteNumber(value: unknown): value is number {
26	  return typeof value === "number" && Number.isFinite(value);
27	}
28	
29	const SERIES_PATTERN = /^[a-z][a-z0-9_.-]*$/;
30	
31	export function isValidSeries(name: unknown): name is string {
32	  return typeof name === "string" && SERIES_PATTERN.test(name);
33	}
34	
35	/**
36	 * Coerce an unknown payload into a Sample, or throw. Never returns a partially
37	 * valid object — callers get all-or-nothing.
38	 */
39	export function validateSample(input: unknown): Sample {
40	  if (input === null || typeof input !== "object") {
41	    throw new ValidationError("sample", "expected an object");
42	  }
43	  const candidate = input as Record<string, unknown>;
44	
45	  if (!isValidSeries(candidate.series)) {
46	    throw new ValidationError(
47	      "series",
48	      "expected a lowercase name matching [a-z][a-z0-9_.-]*",
49	    );
50	  }
51	  if (!isFiniteNumber(candidate.value)) {
52	    throw new ValidationError("value", "expected a finite number");
53	  }
54	  if (!isFiniteNumber(candidate.at) || !Number.isInteger(candidate.at)) {
55	    throw new ValidationError("at", "expected epoch milliseconds as an integer");
56	  }
57	  if (candidate.at < 0) {
58	    throw new ValidationError("at", "expected a non-negative timestamp");
59	  }
60	
61	  return { series: candidate.series, value: candidate.value, at: candidate.at };
62	}
