import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { FixedClock } from "../src/clock.ts";
import { DEFAULT_CONFIG } from "../src/config.ts";
import { createRouter } from "../src/router.ts";
import { MemoryStore } from "../src/store.ts";

describe("Router ingest series cap", () => {
  it("reports a series-cap rejection distinctly, with the accepted count so far", () => {
    const store = new MemoryStore(10, 1);
    const router = createRouter(store, DEFAULT_CONFIG, new FixedClock(0));

    const validReply = router.dispatch("POST", "/samples", "a 1 0");
    assert.equal(validReply.status, 202);

    const overflowReply = router.dispatch("POST", "/samples", "a 1 1\nb 1 1");
    assert.equal(overflowReply.status, 429);
    assert.match(overflowReply.body, /accepted 1/);

    const validationReply = router.dispatch("POST", "/samples", "a not-a-number 1");
    assert.equal(validationReply.status, 400);
    assert.notEqual(validationReply.status, overflowReply.status);
  });
});

